window.AUTH=window.AUTH||{};window.AUTH["17-387"]={"d":"17-387","id":"2017/17-387","n":"Upper Skagit Indian Tribe v. Lundgren","briefs":[{"k":"petitioner","label":"Brief of petitioner Upper Skagit Indian Tribe","date":"2018-01-22","url":"https://www.supremecourt.gov/DocketPDF/17/17-387/28694/20180122141605485_180110%20Merits%20Brief%20for%20Filing.pdf","side":"pet","n":63},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2018-01-29","url":"https://www.supremecourt.gov/DocketPDF/17/17-387/33662/20180129173741245_17-387tsacUnitedStates.pdf","side":"us","n":62},{"k":"respondent","label":"Brief of respondents Sharline Lundgren and Ray Lundgren","date":"2018-02-21","url":"https://www.supremecourt.gov/DocketPDF/17/17-387/36071/20180221123548256_Merits%20Brief.pdf","side":"res","n":90},{"k":"reply","label":"Reply of petitioner Upper Skagit Indian Tribe","date":"2018-03-12","url":"https://www.supremecourt.gov/DocketPDF/17/17-387/38561/20180312142954861_0312%20USIT%20Reply%20Brief%20for%20Petitioner.pdf","side":"pet","n":39}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Adams v. Murphy","cite":"165 F. 304","y":1908,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./165/304/","by":{"0":"15","1":"11"}},{"t":"case","label":"Alden v. Maine","cite":"527 U.S. 706","y":1999,"id":"1998/98-436","sc":1,"sum":"A sharply divided court held in a 5-4 decision that Congress may not use its Article I powers to abrogate the states' sovereign immunity. Both the terms and history of the eleventh amendment suggest that States are immune from suits in their own courts.","sumSrc":"Oyez","by":{"0":"26, 30","2":"31"}},{"t":"case","label":"Alvarado v. Table Mountain Rancheria","cite":"509 F.3d 1008","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/509/1008/","by":{"0":"32"}},{"t":"case","label":"Anderson & Middleton Lumber Co. v. Quinault Indian Nation","cite":"929 P.2d 379","y":1996,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/929/379/","by":{"0":"9, 10","1":"5","2":"11"}},{"t":"case","label":"Belknap v. Schild","cite":"161 U.S. 10","y":1896,"id":"scdb/1895-108","sc":1,"sum":"The United States have no right to use a patented invention without license of the patentee or making compensation to him.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Blatchford v. Native Village of Noatak","cite":"501 U.S. 775","y":1991,"id":"1990/89-1782","sc":1,"sum":"Respondents, Alaska Native villages, brought suit against petitioner, a state official, seeking an order requiring payment to them of money allegedly owed under a state revenue-sharing statute. The District Court dismissed the suit as violating the Eleventh Amendment. The Court of Appeals reversed, first on the ground that 28 U. S. C. § 1362 constituted a congressional abrogation of Eleventh Amendment immunity, and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30","1":"30"}},{"t":"case","label":"California v. Deep Sea Research, Inc.","cite":"523 U.S. 491","y":1998,"id":"1997/96-1400","sc":1,"sum":"In a unanimous opinion the Court held that while precedent interpreting the Eleventh Amendment supports a limited bar on federal admiralty jurisdiction disputes centering on people or property that is in a state's possession, the same does not apply when the concerned state lacks possession of the disputed maritime property.","sumSrc":"Oyez","by":{"0":"27, 28"}},{"t":"case","label":"Carr v. United States","cite":"98 U.S. 433","y":1878,"id":"scdb/1878-112","sc":1,"by":{"0":"23"}},{"t":"case","label":"Cass Cty. Joint Water Res. Dist. v. 1.43 Acres of Land in Highland Twp.","cite":"643 N.W. 2d 685","y":2002,"court":"N.D.","url":"https://www.courtlistener.com/c/N.W.%202d/643/685/","by":{"0":"22"}},{"t":"case","label":"Cayuga Indian Nation of New York v. Seneca County","cite":"890 F. Supp. 2d 240","y":2012,"court":"W.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/890/240/","by":{"0":"20"}},{"t":"case","label":"Cayuga Indian Nation of New York v. Seneca County","cite":"761 F.3d 218","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/761/218/","sum":"Holding that tribal sovereign immunity barred foreclosure proceedings against real property owned by an Indian tribe to recover unpaid property taxes and “declin[ing] to draw the novel distinctions—such as a distinction between in rem and in personam proceedings— that Seneca County has urged [the court] to adopt”.","sumSrc":"brief:1","by":{"0":"20, 23","1":"14, 20, 32"}},{"t":"case","label":"Cherokee Nation v. Georgia","cite":"30 U.S. 1","y":1831,"id":"scdb/1831-041","sc":1,"sum":"Status of Indian nations.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Coast Trading Co., Inc. v. Parmac, Inc.","cite":"587 P.2d 1071","y":1978,"court":"Wash. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/587/1071/","sum":"Noting that an action for “money had and received . . . is looked upon with favor by the courts and is liberally applied” (citation omitted).","sumSrc":"brief:0","by":{"0":"36","2":"39"}},{"t":"case","label":"County of Yakima v. Confederated Tribes & Bands of Yakima Indian Nation","cite":"502 U.S. 251","y":1992,"id":"1991/90-408","sc":1,"sum":"The Indian General Allotment Act of 1887 permits Yakima County to impose an ad valorem tax on reservation land patented in fee pursuant to the Act and owned by reservation Indians or the Yakima Indian Nation itself, but does not allow the county to enforce its excise tax on sales of such land.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"5, 8, 11, 18, 19, 20","2":"5, 33, 36","3":"3, 4"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27, 32","3":"25"}},{"t":"case","label":"First Bank & Tr. v. Maynahonah","cite":"313 P.3d 1044","y":2013,"court":"Okla. Civ. App.","url":"https://www.courtlistener.com/c/P.3d/313/1044/","ar":3,"sum":"Rejecting argument that tribal sovereign immunity did not bar the exercise of in rem jurisdiction over money in a tribal bank account.","sumSrc":"brief:1","by":{"0":"21","1":"14"}},{"t":"case","label":"Florida Dep’t of State v. Treasure Salvors, Inc.","cite":"458 U.S. 670","y":1982,"id":"1981/80-1348","sc":1,"sum":"The Court first held that while a state enjoys limited immunity from federal process under the Eleventh Amendment, its officers do not. In the present case, the seizure warrant was filed against Florida's officers in the Archives.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Foremost-McKesson, Inc. v. Islamic Republic of Iran","cite":"905 F.2d 438","y":1990,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/905/438/","by":{"0":"12, 27"}},{"t":"case","label":"Halverson v. City of Bellevue","cite":"704 P.2d 1232","y":1985,"court":"Wash. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/704/1232/","by":{"0":"36"}},{"t":"case","label":"Hamaatsa, Inc. v. Pueblo of San Felipe","cite":"388 P.3d 977","y":2016,"court":"N.M.","url":"https://www.courtlistener.com/c/P.3d/388/977/","by":{"0":"20"}},{"t":"case","label":"Hess v. Port Auth. Trans-Hudson Corp.","cite":"513 U.S. 30","y":1994,"id":"1994/93-1197","sc":1,"sum":"PATH is not entitled to Eleventh Amendment immunity from suit in federal court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Idaho v. Coeur d’Alene Tribe of Idaho","cite":"521 U.S. 261","y":1997,"id":"1996/94-1474","sc":1,"sum":"Authored by Justice Anthony Kennedy, the Court ruled that the Coeur d'Alene Tribe's suit against the state officials may not proceed in federal court because States enjoy Eleventh Amendment immunity in suits filed by Indian tribes.","sumSrc":"Oyez","by":{"0":"passim","1":"8, 12, 13","2":"17"}},{"t":"case","label":"Kiowa Tribe of Oklahoma v. Mfg. Techs., Inc.","cite":"523 U.S. 751","y":1998,"id":"1997/96-1037","sc":1,"ar":5,"sum":"The Court held that Indian tribes enjoy sovereign immunity from civil suits on contracts, whether those contracts involve governmental or commercial activities and whether they were made on or off a reservation.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"20, 23, 29, 30, 31","3":"6, 7, 13–15, 17–19, 23"}},{"t":"case","label":"Koehler v. United States","cite":"153 F.3d 263","y":1998,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/153/263/","by":{"0":"12, 27"}},{"t":"case","label":"Lundgren v. Upper Skagit Indian Tribe","cite":"389 P.3d 569","y":2017,"court":"Wash.","url":"https://www.courtlistener.com/c/P.3d/389/569/","by":{"0":"passim"}},{"t":"case","label":"Mescalero Apache Tribe v. Jones","cite":"411 U.S. 145","y":1973,"id":"1972/71-738","sc":1,"sum":"The State of New Mexico may impose a nondiscriminatory gross receipts tax on a ski resort operated by petitioner Tribe on offreservation land that the Tribe leased from the Federal Government under § 5 of the Indian Reorganization Act, 25 U. S. C. § 465. Though § 465 exempts the land acquired from state and local taxation, neither that provision nor the federal-instrumentality doctrine bars taxing income from the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6, 17","2":"32"}},{"t":"case","label":"Michigan v. Bay Mills Indian Community","cite":"134 S. Ct. 2024","y":2014,"id":"2013/12-515","sc":1,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"8, 30, 36, 37","3":"2, 5, 8, 10, 11, 13, 15, 16, 18, 19, 23, 25"}},{"t":"case","label":"Moe v. Confederated Salish & Kootenai Tribes","cite":"425 U.S. 463","y":1976,"id":"1975/74-1656","sc":1,"sum":"An Indian tribe and some of its members residing on the tribal reservation in Montana brought actions challenging Montana's cigarette sales taxes and personal property taxes (in particular property taxes on motor vehicles) as applied to reservation Indians, and also the State's vendor licensing statute as applied to tribal members who sell cigarettes at \"smoke shops\" on the reservation, and seeking declaratory and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17, 18, 19, 20","1":"19"}},{"t":"case","label":"Nevada v. Hicks","cite":"533 U.S. 353","y":2001,"id":"2000/99-1994","sc":1,"sum":"A unanimous Court held that \"[b]ecause the Fallon Paiute-Shoshone Tribes lacked legislative authority to restrict, condition, or otherwise regulate the ability of state officials to investigate off-reservation violations of state law, they also lacked adjudicative authority to hear respondent's claim that those officials violated tribal law in the performance of their duties. \"[S]ince the lack of authority is clear,\" continued Scalia, \"there is no need to exhaust the jurisdictional dispute in tribal court.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Okla. Tax Comm’n v. Citizen Band Potawatomi Indian Tribe of Oklahoma","cite":"498 U.S. 505","y":1991,"id":"1990/89-1322","sc":1,"sum":"Under the doctrine of tribal sovereign immunity, a State that has not asserted jurisdiction over Indian lands under Public Law 280 may not tax sales of goods to tribesmen occurring on land held in trust for a federally recognized Indian tribe, but is free to collect taxes on such sales to nonmembers of the tribe.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"10","2":"25, 32","3":"23"}},{"t":"case","label":"Oneida Indian Nation of New York v. Madison County","cite":"401 F. Supp. 2d 219","y":2005,"court":"N.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/401/219/","by":{"0":"21"}},{"t":"case","label":"Oneida Indian Nation of New York v. Madison County","cite":"605 F.3d 149","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/605/149/","by":{"0":"18","1":"32","2":"36"}},{"t":"case","label":"Pan Am. Co. v. Sycuan Band of Mission Indians","cite":"884 F.2d 416","y":1989,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/884/416/","by":{"0":"27"}},{"t":"case","label":"Republic of the Philippines v. Pimentel","cite":"553 U.S. 851","y":2008,"id":"2007/06-1204","sc":1,"sum":"Such a required party must be joined to the suit if it is \"feasible,\" and the Court ruled that the government's inclusion was feasible in this case. The Court sent the case back to the district court with instructions to dismiss the interpleader action. Justice Anthony Kennedy delivered the opinion of the Court in which Justices John Paul Stevens and David Souter concurred in part and dissented in part.","sumSrc":"Oyez","by":{"0":"34, 35","1":"22","2":"18","3":"25"}},{"t":"case","label":"Rhode Island v. Narragansett Indian Tribe","cite":"19 F.3d 685","y":1994,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/19/685/","by":{"0":"14"}},{"t":"case","label":"Santa Clara Pueblo v. Martinez","cite":"436 U.S. 49","y":1978,"id":"1977/76-682","sc":1,"sum":"Respondents, a female member of the Santa Clara Pueblo and her daughter, brought this action for declaratory and injunctive relief against petitioners, the Pueblo and its Governor, alleging that a Pueblo ordinance that denies tribal membership to the children of female members who marry outside the tribe, but not to similarly situated children of men of that tribe, violates Title I of the Indian Civil Rights Act of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10, 14","1":"10","2":"20","3":"24"}},{"t":"case","label":"Save the Valley, LLC v. Santa Ynez Band of Chumash Indians","cite":"2015 WL 12552060","y":2015,"court":"C.D. Cal. July 2","by":{"0":"21"}},{"t":"case","label":"Shaffer v. Heitner","cite":"433 U.S. 186","y":1977,"id":"1976/75-1812","sc":1,"ar":3,"sum":"Appellee, a nonresident of Delaware, filed a shareholder's derivative suit in a Delaware Chancery Court, naming as defendants a corporation and its subsidiary, as well as 28 present or former corporate officers or directors, alleging that the individual defendants had violated their duties to the corporation by causing it and its subsidiary to engage in actions (which occurred in Oregon) that resulted in corporate …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","1":"14, 15","2":"6, 9, 10, 31, 35"}},{"t":"case","label":"Smale v. Noretep","cite":"208 P.3d 1180","y":2009,"court":"Wash. Ct. App.","url":"https://www.courtlistener.com/c/P.3d/208/1180/","by":{"0":"9","1":"3, 4, 5","2":"5"}},{"t":"case","label":"South Dakota v. U.S. Dep’t of Interior","cite":"423 F.3d 790","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/423/790/","by":{"0":"6","3":"11"}},{"t":"case","label":"Stanley v. Schwalby","cite":"162 U.S. 255","y":1896,"id":"scdb/1895-175","sc":1,"sum":"Neither the Secretary of War, nor the Attorney General, nor any subordinate of either, is authorized to waive the exemption of the United States from judicial process, or to submit the United States, or their property, to the jurisdiction of the court in a suit brought against their officers.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Tenn. Student Assistance Corp. v. Hood","cite":"541 U.S. 440","y":2004,"id":"2003/02-1606","sc":1,"sum":"Instead, the Court ruled that discharging a debt owed to a state in a bankruptcy procedure is different from a suit and therefore not barred by sovereign immunity. \"A bankruptcy court is able to provide the debtor a fresh start in this manner ... because the court's jurisdiction is premised on the debtor and his estate, and not on the creditors,\" wrote the Court.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Thebo v. Choctaw Tribe of Indians","cite":"66 F. 372","y":1895,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./66/372/","by":{"0":"15","1":"11"}},{"t":"case","label":"Three Affiliated Tribes of the Fort Berthold Reservation v. Wold Eng’g","cite":"476 U.S. 877","y":1986,"id":"1985/84-1973","sc":1,"sum":"Petitioner Indian tribe brought suit against respondent corporation (hereafter respondent) in a North Dakota state court for negligence and breach of contract in connection with respondent's construction of a water-supply system on petitioner's reservation. The trial court dismissed the suit for lack of jurisdiction. The North Dakota Supreme Court held that a North Dakota statute (Chapter 27-19)-which provides that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14, 15","1":"10","2":"26, 29","3":"22"}},{"t":"case","label":"TransAmerica Assurance Corp. v. United States","cite":"423 F. Supp. 2d 691","y":2006,"court":"W.D. Ky.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/423/691/","by":{"0":"22"}},{"t":"case","label":"United States v. Alabama","cite":"313 U.S. 274","y":1941,"id":"scdb/1940-143","sc":1,"sum":"(1) That'the tax lien is not objectionable under the Federal Colstitution as applied to a purchaser who bought on or after the tax day and before the amount of the tax had been fixed by levy and assessment. P. 279. (2) The fact that the purchaser, in such circumstances, was the United States did not invalidate the lien. P. 281. (3) Such a lien can not be enforced against the United States without its consent.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","1":"8, 12, 17, 21","2":"18"}},{"t":"case","label":"United States v. Nordic Vill., Inc.","cite":"503 U.S. 30","y":1992,"id":"1991/90-1629","sc":1,"sum":"After respondent Nordic Village, Inc., filed a petition for relief under Chapter 11 of the Bankruptcy Code, one of its officers withdrew funds from the company's corporate account. He sent part of the money to the Internal Revenue Service (IRS), directing it to apply the funds against his individual tax liability, which it did. In a subsequent adversary proceeding, the Bankruptcy Court permitted Nordic Village's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22","2":"19"}},{"t":"case","label":"United States v. United States Fid. & Guar. Co.","cite":"309 U.S. 506","y":1940,"id":"scdb/1939-047","sc":1,"sum":"In a reorganization proceeding in the District Court for the Western District of Missouri under § 77B of the Bankruptcy Act, the United States filed a claim in behalf of the Choctaw and Chickasaw Nations. The court allowed it but allowed the debtor's cross-claim for a larger amount and decreed the balance in favor of the debtor against the Nations to be \"collected in the manner provided by law.\" The validity of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15","3":"21"}},{"t":"case","label":"Washington v. Wash. State Commercial Passenger Fishing Vessel Ass’n","cite":"443 U.S. 658","y":1979,"id":"1978/77-983","sc":1,"sum":"In 1854 and 1855, the United States entered into a series of treaties with certain Indian tribes whereby the Indians relinquished their interest in certain lands in what is now the State of Washington in exchange for monetary payments, certain relatively small parcels of land reserved for their exclusive use, and other guarantees, including protection of their \"right of taking fish at usual and accustomed grounds …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5","2":"3"}},{"t":"case","label":"Wis. Dep’t of Nat. Res. v. Timber & Wood Prods. Located in Sawyer Cty., Appeal No. 2017AP181","cite":"2017 WL 6502934","y":2017,"court":"Wis. Ct. App. Dec. 19","by":{"0":"21"}},{"t":"case","label":"Worcester v. Georgia","cite":"31 U.S. 515","y":1832,"id":"1789-1850/31us515","sc":1,"sum":"The Court found that the Georgia legislature lacked the authority to regulate the intercourse between citizens of the state and members of Native American territories.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Young v. Young","cite":"191 P.3d 1258","y":2008,"court":"Wash.","url":"https://www.courtlistener.com/c/P.3d/191/1258/","by":{"0":"36","2":"39"}},{"t":"case","label":"Zych v. Wrecked Vessel Believed to Be the Lady Elgin","cite":"960 F.2d 665","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/960/665/","by":{"0":"22"}},{"t":"const","label":"Article I, Section 8, Clause 3","clauses":[["commerce","Commerce Clause"]],"text":"To regulate Commerce with foreign Nations, and among the several States, and with the Indian Tribes;","by":{"0":"14","3":"23"}},{"t":"const","label":"Article VI, Clause 2","clauses":[["supremacy","Supremacy Clause"]],"text":"This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding.","by":{"0":"3, 13, 33","2":"18","3":"23"}},{"t":"usc","label":"25 U.S.C. § 349","url":"https://www.law.cornell.edu/uscode/text/25/349","stext":{"head":"§349. Patents in fee to allottees","paras":[[0,"At the expiration of the trust period and when the lands have been conveyed to the Indians by patent in fee, as provided in section 348 of this title, then each and every allottee shall have the benefit of and be subject to the laws, both civil and criminal, of the State or Territory in which they may reside; and no Territory shall pass or enforce any law denying any such Indian within its jurisdiction the equal protection of the law: Provided, That the Secretary of the Interior may, in his discretion, and he is authorized, whenever he shall be satisfied that any Indian allottee is competent and capable of managing his or her affairs at any time to cause to be issued to such allottee a patent in fee simple, and thereafter all restrictions as to sale, incumbrance, or taxation of said land shall be removed and said land shall not be liable to the satisfaction of any debt contracted prior to the issuing of such patent: Provided further, That until the issuance of fee-simple patents all allottees to whom trust patents shall be issued shall be subject to the exclusive jurisdiction of the United States: And provided further, That the provisions of this Act shall not extend to any Indians in the former Indian Territory."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/349?type=usc&year=mostrecent&link-type=html"},"head":"§349. Patents in fee to allottees","tname":"Indians","by":{"0":"19","1":"19"}},{"t":"usc","label":"25 U.S.C. § 5108","url":"https://www.law.cornell.edu/uscode/text/25/5108","stext":{"head":"§5108. Acquisition of lands, water rights or surface rights; appropriation; title to lands; tax exemption","paras":[[0,"The Secretary of the Interior is authorized, in his discretion, to acquire, through purchase, relinquishment, gift, exchange, or assignment, any interest in lands, water rights, or surface rights to lands, within or without existing reservations, including trust or otherwise restricted allotments, whether the allottee be living or deceased, for the purpose of providing land for Indians."],[0,"For the acquisition of such lands, interests in lands, water rights, and surface rights, and for expenses incident to such acquisition, there is authorized to be appropriated, out of any funds in the Treasury not otherwise appropriated, a sum not to exceed $2,000,000 in any one fiscal year: Provided, That no part of such funds shall be used to acquire additional land outside of the exterior boundaries of Navajo Indian Reservation for the Navajo Indians in Arizona, nor in New Mexico, in the event that legislation to define the exterior boundaries of the Navajo Indian Reservation in New Mexico, and for other purposes, or similar legislation, becomes law."],[0,"The unexpended balances of any appropriations made pursuant to this section shall remain available until expended."],[0,"Title to any lands or rights acquired pursuant to this Act or the Act of July 28, 1955 (69 Stat. 392), as amended (25 U.S.C. 608 et seq.) 1 shall be taken in the name of the United States in trust for the Indian tribe or individual Indian for which the land is acquired, and such lands or rights shall be exempt from State and local taxation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/5108?type=usc&year=mostrecent&link-type=html"},"head":"§5108. Acquisition of lands, water rights or surface rights; appropriation; title to lands; tax exemption","tname":"Indians","by":{"0":"6","1":"2","2":"33, 34","3":"11, 12"}},{"t":"usc","label":"28 U.S.C. § 1257","url":"https://www.law.cornell.edu/uscode/text/28/1257","subs":["(a)"],"by":{"0":"3"}},{"t":"usc","label":"28 U.S.C. § 2409a","url":"https://www.law.cornell.edu/uscode/text/28/2409a","subs":["(a)","(n)","(g)"],"stext":{"head":"§2409a. Real property quiet title actions","paras":[[0,"(a) The United States may be named as a party defendant in a civil action under this section to adjudicate a disputed title to real property in which the United States claims an interest, other than a security interest or water rights. This section does not apply to trust or restricted Indian lands, nor does it apply to or affect actions which may be or could have been brought under sections 1346, 1347, 1491, or 2410 of this title, sections 7424, 7425, or 7426 of the Internal Revenue Code of 1986, as amended (26 U.S.C. 7424, 7425, and 7426), or section 208 of the Act of July 10, 1952 (43 U.S.C. 666)."],[0,"(b) The United States shall not be disturbed in possession or control of any real property involved in any action under this section pending a final judgment or decree, the conclusion of any appeal therefrom, and sixty days; and if the final determination shall be adverse to the United States, the United States nevertheless may retain such possession or control of the real property or of any part thereof as it may elect, upon payment to the person determined to be entitled thereto of an amount which upon such election the district court in the same action shall determine to be just compensation for such possession or control."],[0,"(c) No preliminary injunction shall issue in any action brought under this section."],[0,"(d) The complaint shall set forth with particularity the nature of the right, title, or interest which the plaintiff claims in the real property, the circumstances under which it was acquired, and the right, title, or interest claimed by the United States."],[0,"(e) If the United States disclaims all interest in the real property or interest therein adverse to the plaintiff at any time prior to the actual commencement of the trial, which disclaimer is confirmed by order of the court, the jurisdiction of the district court shall cease unless it has jurisdiction of the civil action or suit on ground other than and independent of the authority conferred by section 1346(f) of this title."],[0,"(f) A civil action against the United States under this section shall be tried by the court without a jury."],[0,"(g) Any civil action under this section, except for an action brought by a State, shall be barred unless it is commenced within twelve years of the date upon which it accrued. Such action shall be deemed to have accrued on the date the plaintiff or his predecessor in interest knew or should have known of the claim of the United States."],[0,"(h) No civil action may be maintained under this section by a State with respect to defense facilities (including land) of the United States so long as the lands at issue are being used or required by the United States for national defense purposes as determined by the head of the Federal agency with jurisdiction over the lands involved, if it is determined that the State action was brought more than twelve years after the State knew or should have known of the claims of the United States. Upon cessation of such use or requirement, the State may dispute title to such lands pursuant to the provisions of this section. The decision of the head of the Federal agency is not subject to judicial review."],[0,"(i) Any civil action brought by a State under this section with respect to lands, other than tide or submerged lands, on which the United States or its lessee or right-of-way or easement grantee has made substantial improvements or substantial investments or on which the United States has conducted substantial activities pursuant to a management plan such as range improvement, timber harvest, tree planting, mineral activities, farming, wildlife habitat improvement, or other similar activities, shall be barred unless the action is commenced within twelve years after the date the State received notice of the Federal claims to the lands."],[0,"(j) If a final determination in an action brought by a State under this section involving submerged or tide lands on which the United States or its lessee or right-of-way or easement grantee has made substantial improvements or substantial investments is adverse to the United States and it is determined that the State's action was brought more than twelve years after the State received notice of the Federal claim to the lands, the State shall take title to the lands subject to any existing lease, easement, or right-of-way. Any compensation due with respect to such lease, easement, or right-of-way shall be determined under existing law."],[0,"(k) Notice for the purposes of the accrual of an action brought by a State under this section shall be—"],[1,"(1) by public communications with respect to the claimed lands which are sufficiently specific as to be reasonably calculated to put the claimant on notice of the Federal claim to the lands, or"],[1,"(2) by the use, occupancy, or improvement of the claimed lands which, in the circumstances, is open and notorious."],[0,"(l) For purposes of this section, the term \"tide or submerged lands\" means \"lands beneath navigable waters\" as defined in section 2 of the Submerged Lands Act (43 U.S.C. 1301)."],[0,"(m) Not less than one hundred and eighty days before bringing any action under this section, a State shall notify the head of the Federal agency with jurisdiction over the lands in question of the State's intention to file suit, the basis therefor, and a description of the lands included in the suit."],[0,"(n) Nothing in this section shall be construed to permit suits against the United States based upon adverse possession."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2409a?type=usc&year=mostrecent&link-type=html"},"head":"§2409a. Real property quiet title actions","tname":"Judiciary and Judicial Procedure","by":{"0":"28, 28","1":"1, 13, 30, 31, 31, 31","2":"33, 33","3":"12, 21"}},{"t":"reg","label":"25 C.F.R. § 151.10","url":"https://www.ecfr.gov/current/title-25/section-151.10","by":{"0":"6, 31"}},{"t":"reg","label":"25 C.F.R. § 151.11","url":"https://www.ecfr.gov/current/title-25/section-151.11","subs":["(d)"],"by":{"0":"6, 31","2":"34"}},{"t":"case","label":"(III) Cases—Continued: Alabama v. PCI Gaming Auth.","cite":"801 F.3d 1278","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/801/1278/","by":{"1":"17"}},{"t":"case","label":"Alfred Dunhill of London, Inc. v. Republic of Cuba","cite":"425 U.S. 682","y":1976,"id":"1974/73-1288","sc":1,"sum":"The Supreme Court held that the record contained no evidence to support an act of state. There was no statute, decree or order by the Cuban Government refusing to pay, only a statement by the interventor’s counsel during trial. The interventors did not possess governmental power just because the Cuban government appointed them. The affirmative judgment for the one purchaser was restored.","sumSrc":"Oyez","by":{"1":"27","2":"24"}},{"t":"case","label":"Asociacion de Reclamantes v. United Mexican States","cite":"735 F.2d 1517","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/735/1517/","by":{"1":"28","2":"14, 15, 19","3":"22"}},{"t":"case","label":"Block v. North Dakota","cite":"461 U.S. 273","y":1983,"id":"1982/81-2337","sc":1,"ar":1,"sum":"North Dakota filed suit in Federal District Court against several federal officials to resolve a dispute as to ownership of certain portions of a riverbed within the State. The United States claims title to most of the disputed area on the basis of its status as a riparian landowner on a nonnavigable river, while the State asserts that the river was navigable when North Dakota was admitted to the Union in 1889 and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13, 23","2":"18","3":"23"}},{"t":"case","label":"Bodi v. Shingle Springs Band of Miwok Indians","cite":"832 F.3d 1011","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/832/1011/","by":{"1":"17"}},{"t":"case","label":"Breakthrough Mgmt. Grp., Inc. v. Chukchansi Gold Casino & Resort","cite":"629 F.3d 1173","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/629/1173/","by":{"1":"17"}},{"t":"case","label":"El Cerrito, Inc. v. Ryndak","cite":"376 P.2d 528","y":1962,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/376/528/","by":{"1":"22, 23"}},{"t":"case","label":"Franchise Tax Board v. Hyatt","cite":"136 S. Ct. 1277","y":2016,"id":"2015/14-1175","sc":1,"sum":"The Court determined that the Constitution does not allow Nevada to refuse to extend to other states haled into Nevada courts the same immunities Nevada would receive in those courts.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Georgia v. City of Chattanooga","cite":"264 U.S. 472","y":1924,"id":"scdb/1923-112","sc":1,"sum":"1. Land acquired and held for railway purposes by one State within the borders of another with the latter's consent remains subject to the eminent domain of the State in which it lies and subject to be condemned by that State, or her authorized municipality, for a public street, in proceedings against the owner State, even though she has not consented to be sued.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"28, 29","2":"7, 16, 24, 25","3":"17, 18"}},{"t":"case","label":"Gorman v. City of Woodinville","cite":"283 P.3d 1082","y":2012,"court":"Wash.","url":"https://www.courtlistener.com/c/P.3d/283/1082/","by":{"1":"23","2":"38"}},{"t":"case","label":"Guaranty Trust Co. v. United States","cite":"304 U.S. 126","y":1938,"id":"scdb/1937-044","sc":1,"sum":"1. The rule which exempts the United States and the States from the operation of statutes of limitations rests not upon any inherited notion of royal prerogative but upon the public policy of protecting the public rights, and thereby the citizen, from injury through negligence of public officers.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Haberman v. Washington Pub. Power Supply Sys.","cite":"744 P.2d 1032","y":1987,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/744/1032/","by":{"1":"28"}},{"t":"case","label":"International Shoe Co. v. Washington","cite":"326 U.S. 310","y":1945,"id":"scdb/1945-002","sc":1,"ar":1,"sum":"Activities within a State of salesmen in the employ of a foreign corporation, exhibiting samples of merchandise and soliciting orders from prospective buyers to be accepted or rejected by the corporation at a point outside the State, were systematic and continuous, and resulted in a large volume of interstate business. A statute of the State requires employers to pay into the state unemployment compensation fund a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15","2":"10"}},{"t":"case","label":"Lewis v. Clarke","cite":"137 S. Ct. 1285","y":2017,"id":"2016/15-1500","sc":1,"ar":3,"sum":"The Court determined that tribal sovereign immunity is not implicated in a suit against a tribal employee in his individual capacity, and an indemnification provision cannot extend tribal sovereign immunity to conduct that it would not otherwise cover.","sumSrc":"Oyez","by":{"1":"14","2":"8, 20, 26, 40","3":"5, 22, 25"}},{"t":"case","label":"Match-E-Be-Nash-She-Wish Band of Pottawatomi Indians v. Patchak","cite":"567 U.S. 209","y":2012,"id":"2011/11-246","sc":1,"sum":"The Court held that a neighbor of a proposed Indian casino had standing to sue the government for taking 147 acres of a town's land under Section 465 of the Indian Reorganization Act.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Miner Elec., Inc. v. Muscogee (Creek) Nation","cite":"505 F.3d 1007","y":2007,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/505/1007/","by":{"1":"17"}},{"t":"case","label":"Minnesota v. United States","cite":"305 U.S. 382","y":1939,"id":"scdb/1938-118","sc":1,"ar":2,"sum":"1. The United States is an indispensable party defendant in a condemnation proceeding brought by a State to acquire a right of way over lands which the United States owns in fee and holds in trust for Indian allottees.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12, 17","2":"18"}},{"t":"case","label":"Mullane v. Central Hanover Bank & Trust Co.","cite":"339 U.S. 306","y":1950,"id":"scdb/1949-066","sc":1,"sum":"A trust company in New York which had exclusive management and control of a common trust fund established by it under § 100-c of the New York Banking Law petitioned under that section for a judicial settlement of accounts which would be binding and conclusive as to any matter set forth therein upon everyone having any interest in the common fund or in any participating trust. In this common fund the trust company …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"National Farmers Union Ins. Cos. v. Crow Tribe of Indians","cite":"471 U.S. 845","y":1985,"id":"1984/84-320","sc":1,"sum":"Respondent Crow Indian minor was struck by a motorcycle in the parking lot of a school located within the Crow Indian Reservation but on land owned by the State of Montana. Through his guardian, the minor brought a damages action in the Crow Tribal Court against petitioner School District, a political subdivision of the State, and obtained a default judgment. Thereafter, the School District and its insurer, also a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"1"}},{"t":"case","label":"Nevada v. Hall","cite":"440 U.S. 410","y":1979,"id":"1978/77-1337","sc":1,"sum":"A State is not constitutionally immune from suit in the courts of another State.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"9, 28","2":"24","3":"17"}},{"t":"case","label":"Permanent Mission of India v. City of New York","cite":"551 U.S. 193","y":2007,"id":"2006/06-134","sc":1,"sum":"The Court held 7-2 that the \"immovable property\" exception to sovereign immunity in the FSIA covers disputes over tax liens on the property as well as disputes over ownership and possession. The opinion by Justice Clarence Thomas ruled that a tax lien, by both its dictionary definition and its practical effect, is an interest or right in property.","sumSrc":"Oyez","by":{"1":"27, 32","2":"15, 31, 35"}},{"t":"case","label":"Phillips v. Thompson","cite":"131 P. 461","y":1913,"court":"Wash.","url":"https://www.courtlistener.com/c/P./131/461/","by":{"1":"15, 16","2":"9, 10, 35"}},{"t":"case","label":"Puyallup Tribe, Inc. v. Department of Game","cite":"433 U.S. 165","y":1977,"id":"1976/76-423","sc":1,"sum":"After protracted litigation the Washington Superior Court entered a judgment against petitioner Puyallup Tribe reciting that the court possessed jurisdiction to regulate the Tribe's fishing activities both off and on its reservation, and limiting the number of steelhead trout that tribal members might net in the Puyallup River each year, and the Tribe was directed to file a list of members authorized to exercise …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"10","3":"14, 15, 18, 19"}},{"t":"case","label":"State v. Superior Court","cite":"94 P.2d 505","y":1939,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/94/505/","sum":"Stating that “an action * * * to determine the title to real property” “may not be maintained against the [S]tate without its consent”.","sumSrc":"brief:1","by":{"1":"13","2":"18"}},{"t":"case","label":"Travelers Indem. Co. v. Bailey","cite":"557 U.S. 137","y":2009,"id":"2008/08-295","sc":1,"sum":"The Court held that federal bankruptcy courts have jurisdiction to enter orders beyond matters directly related to the execution of a debtor's estate.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Verlinden B.V. v. Central Bank of Nigeria","cite":"461 U.S. 480","y":1983,"id":"1982/81-920","sc":1,"ar":1,"sum":"The Supreme Court held that the FSIA does not violate Article III. The FSIA was a valid exercise of Congress’ power to regulate foreign commerce. On remand, the court of appeals should consider whether Central Bank is entitled to sovereign immunity.","sumSrc":"Oyez","by":{"1":"26, 27, 29","2":"23","3":"6–8, 19"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"1":"15"}},{"t":"usc","label":"28 U.S.C. § 1330","url":"https://www.law.cornell.edu/uscode/text/28/1330","subs":["(a)"],"by":{"1":"9, 25, 26"}},{"t":"usc","label":"28 U.S.C. § 1604","url":"https://www.law.cornell.edu/uscode/text/28/1604","stext":{"head":"§1604. Immunity of a foreign state from jurisdiction","paras":[[0,"Subject to existing international agreements to which the United States is a party at the time of enactment of this Act a foreign state shall be immune from the jurisdiction of the courts of the United States and of the States except as provided in sections 1605 to 1607 of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1604?type=usc&year=mostrecent&link-type=html"},"head":"§1604. Immunity of a foreign state from jurisdiction","tname":"Judiciary and Judicial Procedure","by":{"1":"26","3":"7"}},{"t":"usc","label":"28 U.S.C. § 1605","url":"https://www.law.cornell.edu/uscode/text/28/1605","subs":["(a)(2)","(a)(4)"],"stext":{"head":"§1605. General exceptions to the jurisdictional immunity of a foreign state","paras":[[0,"(a) A foreign state shall not be immune from the jurisdiction of courts of the United States or of the States in any case—"],[1,"(1) in which the foreign state has waived its immunity either explicitly or by implication, notwithstanding any withdrawal of the waiver which the foreign state may purport to effect except in accordance with the terms of the waiver;"],[1,"(2) in which the action is based upon a commercial activity carried on in the United States by the foreign state; or upon an act performed in the United States in connection with a commercial activity of the foreign state elsewhere; or upon an act outside the territory of the United States in connection with a commercial activity of the foreign state elsewhere and that act causes a direct effect in the United States;"],[1,"(3) in which rights in property taken in violation of international law are in issue and that property or any property exchanged for such property is present in the United States in connection with a commercial activity carried on in the United States by the foreign state; or that property or any property exchanged for such property is owned or operated by an agency or instrumentality of the foreign state and that agency or instrumentality is engaged in a commercial activity in the United States;"],[1,"(4) in which rights in property in the United States acquired by succession or gift or rights in immovable property situated in the United States are in issue;"],[1,"(5) not otherwise encompassed in paragraph (2) above, in which money damages are sought against a foreign state for personal injury or death, or damage to or loss of property, occurring in the United States and caused by the tortious act or omission of that foreign state or of any official or employee of that foreign state while acting within the scope of his office or employment; except this paragraph shall not apply to—"],[2,"(A) any claim based upon the exercise or performance or the failure to exercise or perform a discretionary function regardless of whether the discretion be abused, or"],[2,"(B) any claim arising out of malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights; or"],[1,"(6) in which the action is brought, either to enforce an agreement made by the foreign state with or for the benefit of a private party to submit to arbitration all or any differences which have arisen or which may arise between the parties with respect to a defined legal relationship, whether contractual or not, concerning a subject matter capable of settlement by arbitration under the laws of the United States, or to confirm an award made pursuant to such an agreement to arbitrate, if (A) the arbitration takes place or is intended to take place in the United States, (B) the agreement or award is or may be governed by a treaty or other international agreement in force for the United States calling for the recognition and enforcement of arbitral awards, (C) the underlying claim, save for the agreement to arbitrate, could have been brought in a United States court under this section or section 1607, or (D) paragraph (1) of this subsection is otherwise applicable."],[0,"(b) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any case in which a suit in admiralty is brought to enforce a maritime lien against a vessel or cargo of the foreign state, which maritime lien is based upon a commercial activity of the foreign state: Provided, That—"],[1,"(1) notice of the suit is given by delivery of a copy of the summons and of the complaint to the person, or his agent, having possession of the vessel or cargo against which the maritime lien is asserted; and if the vessel or cargo is arrested pursuant to process obtained on behalf of the party bringing the suit, the service of process of arrest shall be deemed to constitute valid delivery of such notice, but the party bringing the suit shall be liable for any damages sustained by the foreign state as a result of the arrest if the party bringing the suit had actual or constructive knowledge that the vessel or cargo of a foreign state was involved; and"],[1,"(2) notice to the foreign state of the commencement of suit as provided in section 1608 of this title is initiated within ten days either of the delivery of notice as provided in paragraph (1) of this subsection or, in the case of a party who was unaware that the vessel or cargo of a foreign state was involved, of the date such party determined the existence of the foreign state's interest."],[0,"(c) Whenever notice is delivered under subsection (b)(1), the suit to enforce a maritime lien shall thereafter proceed and shall be heard and determined according to the principles of law and rules of practice of suits in rem whenever it appears that, had the vessel been privately owned and possessed, a suit in rem might have been maintained. A decree against the foreign state may include costs of the suit and, if the decree is for a money judgment, interest as ordered by the court, except that the court may not award judgment against the foreign state in an amount greater than the value of the vessel or cargo upon which the maritime lien arose. Such value shall be determined as of the time notice is served under subsection (b)(1). Decrees shall be subject to appeal and revision as provided in other cases of admiralty and maritime jurisdiction. Nothing shall preclude the plaintiff in any proper case from seeking relief in personam in the same action brought to enforce a maritime lien as provided in this section."],[0,"(d) A foreign state shall not be immune from the jurisdiction of the courts of the United States in any action brought to foreclose a preferred mortgage, as defined in section 31301 of title 46. Such action shall be brought, heard, and determined in accordance with the provisions of chapter 313 of title 46 and in accordance with the principles of law and rules of practice of suits in rem, whenever it appears that had the vessel been privately owned and possessed a suit in rem might have been maintained."],[0,"[(e), (f) Repealed. Pub. L. 110–181, div. A, title X, §1083(b)(1)(B), Jan. 28, 2008, 122 Stat. 341.]"],[0,"(g) Limitation on Discovery.—"],[1,"(1) In general.—(A) Subject to paragraph (2), if an action is filed that would otherwise be barred by section 1604, but for section 1605A or section 1605B, the court, upon request of the Attorney General, shall stay any request, demand, or order for discovery on the United States that the Attorney General certifies would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action, until such time as the Attorney General advises the court that such request, demand, or order will no longer so interfere."],[1,"(B) A stay under this paragraph shall be in effect during the 12-month period beginning on the date on which the court issues the order to stay discovery. The court shall renew the order to stay discovery for additional 12-month periods upon motion by the United States if the Attorney General certifies that discovery would significantly interfere with a criminal investigation or prosecution, or a national security operation, related to the incident that gave rise to the cause of action."],[1,"(2) Sunset.—(A) Subject to subparagraph (B), no stay shall be granted or continued in effect under paragraph (1) after the date that is 10 years after the date on which the incident that gave rise to the cause of action occurred."],[1,"(B) After the period referred to in subparagraph (A), the court, upon request of the Attorney General, may stay any request, demand, or order for discovery on the United States that the court finds a substantial likelihood would—"],[2,"(i) create a serious threat of death or serious bodily injury to any person;"],[2,"(ii) adversely affect the ability of the United States to work in cooperation with foreign and international law enforcement agencies in investigating violations of United States law; or"],[2,"(iii) obstruct the criminal case related to the incident that gave rise to the cause of action or undermine the potential for a conviction in such case."],[1,"(3) Evaluation of evidence.—The court's evaluation of any request for a stay under this subsection filed by the Attorney General shall be conducted ex parte and in camera."],[1,"(4) Bar on motions to dismiss.—A stay of discovery under this subsection shall constitute a bar to the granting of a motion to dismiss under rules 12(b)(6) and 56 of the Federal Rules of Civil Procedure."],[1,"(5) Construction.—Nothing in this subsection shall prevent the United States from seeking protective orders or asserting privileges ordinarily available to the United States."],[0,"(h) Jurisdictional Immunity for Certain Art Exhibition Activities.—"],[1,"(1) In general.—If—"],[2,"(A) a work is imported into the United States from any foreign state pursuant to an agreement that provides for the temporary exhibition or display of such work entered into between a foreign state that is the owner or custodian of such work and the United States or one or more cultural or educational institutions within the United States;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1605?type=usc&year=mostrecent&link-type=html"},"head":"§1605. General exceptions to the jurisdictional immunity of a foreign state","tname":"Judiciary and Judicial Procedure","by":{"1":"26, 29, 9, 26, 30, 32","2":"15","3":"7, 19"}},{"t":"usc","label":"25 U.S.C. § 461","url":"https://www.law.cornell.edu/uscode/text/25/461","by":{"1":"18"}},{"t":"reg","label":"25 C.F.R. § 151.13","url":"https://www.ecfr.gov/current/title-25/section-151.13","subs":["(b)"],"by":{"1":"24","2":"34","3":"11"}},{"t":"rule","label":"Fed. R. Civ. P. 19","url":"https://www.law.cornell.edu/rules/frcp/rule_19","by":{"1":"22","2":"6"}},{"t":"reg","label":"46 Fed. Reg. 46,681","url":"https://www.govinfo.gov/link/fr/46/46681","by":{"1":"2","2":"3, 11"}},{"t":"case","label":"Alaska v. Native Vill. of Venetie Tribal Gov’t","cite":"522 U.S. 520","y":1998,"id":"1997/96-1577","sc":1,"sum":"The Court held that the Tribe's land is not \"Indian country.\" \"As noted, only one Indian reservation, the Annette Island Reserve, survived ANCSA,\" explained Justice Thomas in a footnote, [o]ther Indian country exists in Alaska post-ANCSA only if the land in question meets the requirements of a 'dependent Indian community' under our interpretation of [18 USC section 1151 (b)], or if it constitutes 'allotments' under [18 USC section 1151 (c)].\" \"The Tribe's ANCSA lands do not satisfy either of these requirements,\" concluded Justice Thomas, \"[a]fter the enactment of ANCSA, the Tribe's lands are neither 'validly set apart for the use of the Indians as such,' nor are they under the superintendence of the Federal Government.\".","sumSrc":"Oyez","by":{"2":"33"}},{"t":"case","label":"Allergan, Inc. v. Teva Pharm. USA, Inc.","cite":"2017 WL 4619790","y":2017,"court":"E.D. Tex. Oct. 16","by":{"2":"37"}},{"t":"case","label":"Arndt v. Griggs","cite":"134 U.S. 316","y":1890,"id":"scdb/1889-173","sc":1,"sum":"A State may provide by statute that the title to real estate within its limits shall he settled and determined by a suit in which.the defendant, being a non-resident, is brought into court by publication.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"9, 10, 13"}},{"t":"case","label":"Brendale v. Confederated Tribes & Bands of the Yakima Indian Nation","cite":"492 U.S. 408","y":1989,"id":"1988/87-1622","sc":1,"sum":"The treaty between the United States and the Yakima Indian Nation (Yakima Nation or Tribe) provided that the Tribe would retain its reservation for its \"exclusive use and benefit,\" and that \"no white man [shall] be permitted to reside upon the said reservation without [the Tribe's] permission.\" Much of the reservation is located in Yakima County, Washington. Roughly 80% of the reservation land is held in trust by …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"V Cases—Continued: Burbank v. Fay","cite":"65 N.Y. 57","y":1875,"url":"https://www.courtlistener.com/c/N.Y./65/57/","by":{"2":"17"}},{"t":"case","label":"C & L Enters., Inc. v. Citizen Band Potawatomi Indian Tribe of Okla.","cite":"532 U.S. 411","y":2001,"id":"2000/00-292","sc":1,"sum":"The Court held that \"under the agreement the Tribe proposed and signed, the Tribe clearly consented to arbitration and to the enforcement of arbitral awards in Oklahoma state court; the Tribe thereby waived its sovereign immunity from C & L's suit.\" Justice Ginsburg wrote for the Court that \"the Tribe agreed, by express contract, to adhere to certain dispute resolution procedures.\".","sumSrc":"Oyez","by":{"2":"20","3":"14, 15, 19"}},{"t":"case","label":"Cass County v. Leech Lake Band of Chippewa Indians","cite":"524 U.S. 103","y":1998,"id":"1997/97-174","sc":1,"sum":"The Court held that ad valorem taxes may be imposed upon such land. \"When Congress makes Indian reservation land freely alienable, it manifests an unmistakably clear intent to render such land subject to state and local taxation,\" wrote Justice Thomas. Repurchasing the land by an Indian tribe does not return the land to tax-exempt status.","sumSrc":"Oyez","by":{"2":"34"}},{"t":"case","label":"Cass Cty. Joint Water Res. Dist. v. 1.43 Acres of Land in Highland Twp.","cite":"643 N.W.2d 685","y":2002,"court":"N.D.","url":"https://www.courtlistener.com/c/N.W.2d/643/685/","by":{"2":"22, 37"}},{"t":"case","label":"City of New York v. Permanent Mission of India","cite":"446 F.3d 365","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/446/365/","by":{"2":"13"}},{"t":"case","label":"City of Sherrill v. Oneida Indian Nation of N.Y.","cite":"544 U.S. 197","y":2005,"id":"2004/03-855","sc":1,"ar":1,"sum":"The Court held that standards of federal Indian law and federal equity precluded the Tribe from unilaterally reviving its ancient sovereignty over the land at issue.","sumSrc":"Oyez","by":{"2":"passim","3":"14, 15"}},{"t":"case","label":"Cory v. White","cite":"457 U.S. 85","y":1982,"id":"1981/80-1556","sc":1,"sum":"The Eleventh Amendment bars the statutory interpleader action. Worcester County Trust Co. v. Riley, 302 U. S. 292. Contrary to the Court of Appeals' view, Edelmanv. Jordan,415 U. S. 651, did not overrule Worcester County Trust Co. Pp. 89-91. 629 F. 2d 397, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18"}},{"t":"case","label":"Cox v. O’Brien","cite":"206 P.3d 682","y":2009,"court":"Wash. Ct. App.","url":"https://www.courtlistener.com/c/P.3d/206/682/","by":{"2":"39"}},{"t":"case","label":"Crafts v. Pitts","cite":"162 P.3d 382","y":2007,"court":"Wash.","url":"https://www.courtlistener.com/c/P.3d/162/382/","by":{"2":"39"}},{"t":"case","label":"De Coteau v. District Cty. Court","cite":"420 U.S. 425","y":1975,"id":"1974/73-1148","sc":1,"sum":"The Lake Traverse Indian Reservation in South Dakota, created by an 1867 treaty, held terminated and returned to the public domain by an 1891 Act which, in ratification of a previously negotiated 1889 Agreement between the affected Indian tribe and the United States, not only opened all unallotted lands to settlement but also appropriated and vested in the tribe a sum certain per acre in payment for the express …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"33"}},{"t":"case","label":"Duro v. Reina","cite":"495 U.S. 676","y":1990,"id":"1989/88-6546","sc":1,"sum":"An Indian tribe may not assert criminal jurisdiction over a nonmember Indian.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"36"}},{"t":"case","label":"Federal Mar. Comm’n v. South Carolina State Ports Auth.","cite":"535 U.S. 743","y":2002,"id":"2001/01-46","sc":1,"sum":"The Court held that state sovereign immunity bars the FMC from adjudicating a private party's complaint against a nonconsenting State. Historically, the Court noted, states were not subject to private suits in administrative adjudications when the Constitution was adopted, and states were thus presumptively immune from such actions.","sumSrc":"Oyez","by":{"2":"31"}},{"t":"case","label":"Mattz v. Arnett","cite":"412 U.S. 481","y":1973,"id":"1972/71-1182","sc":1,"sum":"The Klamath River Reservation was not terminated by the Act of June 17, 1892, and the land within the reservation boundaries is still Indian country, within theoneaning of 18 U. S. C. § 1151.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"11"}},{"t":"case","label":"McClanahan v. Arizona State Tax Comm’n","cite":"411 U.S. 164","y":1973,"id":"1972/71-834","sc":1,"sum":"The Court reversed the decision of the Arizona Court of Appeals and held that Arizona did not have the right to tax McClanahan. In an opinion authored by Justice Thurgood Marshall, the Court emphasized the long-standing status of Indian reservations as exempt from state authority.","sumSrc":"Oyez","by":{"2":"28, 31"}},{"t":"case","label":"Missouri v. Fiske","cite":"290 U.S. 18","y":1933,"id":"scdb/1933-007","sc":1,"sum":"1. A State may. waive, by appearing, its immunity as a sovereign from being sued by individuals.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"Montana v. United States","cite":"450 U.S. 544","y":1981,"id":"1980/79-1128","sc":1,"sum":"By a tribal regulation, the Crow Tribe of Montana sought to prohibit hunting and fishing within its reservation by anyone who is not a member of the Tribe. Relying on its purported ownership of the bed of the Big Horn River, on treaties which created its reservation, and on its inherent power as a sovereign, the Tribe claimed authority to prohibit hunting and fishing by nonmembers of the Tribe even on lands within …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"Nebraska v. Parker","cite":"136 S. Ct. 1072","y":2016,"id":"2015/14-1406","sc":1,"sum":"The Court determined that the passage of the 1882 Act by Congress did not diminish the original boundaries of the Omaha Indian Reservation.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"New Mexico v. Mescalero Apache Tribe","cite":"462 U.S. 324","y":1983,"id":"1982/82-331","sc":1,"ar":1,"sum":"The application of New Mexico's laws to on-reservation hunting and fishing by nonmembers of the Tribe is pre-empted by the operation of federal law.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"31"}},{"t":"case","label":"Ohio v. Robinette","cite":"519 U.S. 33","y":1996,"id":"1996/95-891","sc":1,"sum":"After establishing its federal jurisdiction, despite a claim that the matter involved aspects of Ohio's Constitution, the Court held that when looking at the totality of the circumstances it may be reasonably concluded that if a defendant consents to be searched, even if not first advised that he is \"free to go,\" the ensuing search will be recognized as voluntary.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Oklahoma Tax Comm’n v. Chickasaw Nation","cite":"515 U.S. 450","y":1995,"id":"1994/94-771","sc":1,"sum":"from enforcing several state taxes against the Tribe and its members. Pertinent here, the District Court held for the State on the motor fuels tax question, and largely for the Tribe on the income tax issue. The Court of Appeals ruled for the Tribe and its members on both issues, determining: (1) that, without congressional authorization, the State could not impose a motor fuels tax on fuel sold by the Tribe at its …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8, 27"}},{"t":"case","label":"Oneida Tribe of Indians of Wis. v. Village of Hobart","cite":"542 F. Supp. 2d 908","y":2008,"court":"E.D. Wis.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/542/908/","by":{"2":"36"}},{"t":"case","label":"Pennoyer v. Neff","cite":"95 U.S. 714","y":1878,"id":"scdb/1877-123","sc":1,"sum":"1. A statute of Oregon, after providing for service of summons upon parties or their representatives, personally or at their residence, declares that when service cannot be thus made, and the defendant, after due diligence, eann.ot be found within the State, and “ that fact appears, by affidavit, to the satisfaction of the court or judge thereof, and it, in like manner, appears that a cause of action exists against …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"9"}},{"t":"case","label":"People v. Streeper","cite":"145 N.E.2d 625","y":1957,"court":"Ill.","url":"https://www.courtlistener.com/c/N.E.2d/145/625/","sum":"Holding that a State or its municipality owning property in Illinois “occupies the same position here as a private entity”.","sumSrc":"brief:2","by":{"2":"16, 17"}},{"t":"case","label":"Plains Commerce Bank v. Long Family Land & Cattle Co.","cite":"554 U.S. 316","y":2008,"id":"2007/07-411","sc":1,"ar":1,"sum":"On this issue, the Court held unanimously that tribal courts do not have jurisdiction to hear disputes concerning non- Indian banks' sales of their own lands. Writing for the Court, Chief Justice John G. Roberts stated that although tribal courts have jurisdiction to regulate conduct occurring on tribal lands, that jurisdiction is lost once title to the land passes into the hands of non-Indians.","sumSrc":"Oyez","by":{"2":"28, 29, 32"}},{"t":"case","label":"Rice v. Rehner","cite":"463 U.S. 713","y":1983,"id":"1982/82-401","sc":1,"sum":"California may properly require respondent to obtain a state license in order to sell liquor for off-premises consumption.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27"}},{"t":"case","label":"Richlin Sec. Serv. Co. v. Chertoff","cite":"553 U.S. 571","y":2008,"id":"2007/06-1717","sc":1,"sum":"The Court held that such paralegal fees are recoverable at market rates. Justice Samuel A. Alito stated that because Richlin incurred fees for paralegal services in connection with its case, a straightforward reading of the statute demonstrates that Richlin was entitled to recover fees for the paralegal services it purchased at the market rate.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Robinson v. Khan","cite":"948 P.2d 1347","y":1998,"court":"Wash. Ct. App.","url":"https://www.courtlistener.com/c/P.2d/948/1347/","by":{"2":"40"}},{"t":"case","label":"Seminole Tribe of Fla. v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"State v. City of Hudson","cite":"42 N.W.2d 546","y":1950,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W.2d/42/546/","by":{"2":"16"}},{"t":"case","label":"Taylor v. Sturgell","cite":"553 U.S. 880","y":2008,"id":"2007/07-371","sc":1,"sum":"Writing for a unanimous Court, Justice Ruth Bader Ginsburg held that such \"nonparty preclusion\" runs up against the \"deep-rooted historic tradition that everyone should have his own day in court.\" Virtual representation should only be applied rarely and under certain exceptions to the general rule, none of which the Court found applicable in this case.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"United States v. Fox","cite":"94 U.S. 315","y":1877,"id":"scdb/1876-171","sc":1,"sum":"In February, 1870, Charles Fox, of the city of New York, died possessed of certain personal and real property situated in the State of New York. By his last will and testament, he devised and bequeathed the whole property, after the payment of his debts, to the government of the United States, for the purpose of assisting to discharge the debt created by the war of the Rebellion. By the government of the United …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"35"}},{"t":"case","label":"United States v. Grubbs","cite":"547 U.S. 90","y":2006,"id":"2005/04-1414","sc":1,"sum":"Justice Antonin Scalia, in the majority opinion, wrote that under the Fourth Amendment's particularity requirement a warrant need not set out the conditions that trigger it, only the place to be searched and the persons or things to be searched for. The fact that the triggering conditions were included in the affidavit, even if they were never showed to Grubbs, was therefore sufficient.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"United States v. Kagama","cite":"118 U.S. 375","y":1886,"id":"1850-1900/118us375","sc":1,"sum":"The Court acknowledged, \"The Constitution of the United States is almost silent in regard to the relations of the government which was established by it to the numerous tribes of Indians within its borders.\" Nonetheless, the Court reasoned that, because the tribal governments \"owe all their powers to the statutes of the United States conferring on them the powers which they exercise, and which are liable to be withdrawn, modified, or repealed at any time by Congress,\" the legislature could therefore control jurisdiction of crimes committed within reservations.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"United States v. Lara","cite":"541 U.S. 193","y":2004,"id":"2003/03-107","sc":1,"sum":"In an opinion written by Justice Stephen G. Breyer and joined by Chief Justice Rehnquist and three other Justices, the Court found that the right to prosecute nonmember Indians is inherent in the sovereignty of Native American tribes.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"United States v. Mottaz","cite":"476 U.S. 834","y":1986,"id":"1985/85-546","sc":1,"sum":"Respondent's suit is \"a civil action... to adjudicate a disputed title to real property in which the United States claims an interest,\" within the meaning of the Quiet Title Act, and therefore is barred by that Act's 12-year limitations period.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"34"}},{"t":"case","label":"United States v. Wheeler","cite":"435 U.S. 313","y":1978,"id":"1977/76-1629","sc":1,"sum":"The Double Jeopardy Clause does not bar the federal prosecution.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"28"}},{"t":"case","label":"Washington v. Confederated Tribes of the Colville Indian Reservation","cite":"447 U.S. 134","y":1980,"id":"1979/78-630","sc":1,"sum":"These cases concern challenges of several Indian Tribes to efforts by the State of Washington to apply various state taxes and other laws to transactions and activities occurring on Indian reservations. Washington imposes a cigarette excise tax on the \"sale, use, consumption, handling, possession or distribution\" of cigarettes within the State. It also imposes a general retail sales tax on sales of personal …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25, 32","3":"22"}},{"t":"case","label":"Whitney v. City of Port Huron","cite":"50 N.W. 316","y":1891,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./50/316/","by":{"2":"41"}},{"t":"law","label":"Pub. L. No. 94-583","url":"https://www.govinfo.gov/link/statute/90/2891","by":{"2":"15"}},{"t":"law","label":"Pub. L. No. 115-121","url":"https://www.govinfo.gov/link/plaw/115/public/121","by":{"2":"36"}},{"t":"usc","label":"25 U.S.C. § 71","url":"https://www.law.cornell.edu/uscode/text/25/71","by":{"2":"27"}},{"t":"usc","label":"28 U.S.C. § 1333","url":"https://www.law.cornell.edu/uscode/text/28/1333","by":{"2":"19"}},{"t":"usc","label":"28 U.S.C. § 1334","url":"https://www.law.cornell.edu/uscode/text/28/1334","subs":["(a)"],"by":{"2":"19"}},{"t":"reg","label":"25 C.F.R. § 1.4","url":"https://www.ecfr.gov/current/title-25/section-1.4","by":{"2":"33"}},{"t":"reg","label":"83 Fed. Reg. 4235","url":"https://www.govinfo.gov/link/fr/83/4235","by":{"2":"36"}},{"t":"case","label":"Empire Oil Co. v. Lynch","cite":"126 S.E.2d 478","y":1962,"court":"Ga. Ct. App.","url":"https://www.courtlistener.com/c/S.E.2d/126/478/","by":{"3":"24"}},{"t":"case","label":"Heckman v. United States","cite":"224 U.S. 413","y":1912,"id":"scdb/1911-217","sc":1,"sum":"The United States has capacity to maintain a suit to set aside conveyances made by allottee Indians of allotted lands within the statutory period of restriction; and this suit brought against numerous defendants, all of whom were grantees of allottees of the same tribe, is properly maintainable in equity; the return of the consideration to the grantee is not essential; there is no defect of parties because the …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"21"}},{"t":"case","label":"Knocklong Corp. v. Kingdom of Afghanistan","cite":"167 N.Y.S.2d 285","y":1957,"court":"Nassau Cty. Ct.","url":"https://www.courtlistener.com/c/N.Y.S.2d/167/285/","by":{"3":"8"}},{"t":"case","label":"Nev. Comm’n on Ethics v. Carrigan","cite":"564 U.S. 117","y":2011,"id":"2010/10-568","sc":1,"sum":"The Court held that the Nevada law requiring elected officials to disqualify themselves when they are asked to vote on matters that present a conflict of interest was constitutional.","sumSrc":"Oyez","by":{"3":"3"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"136 S. Ct. 390","y":2015,"id":"2015/13-1067","sc":1,"sum":"The Court held that the commercial activity exception to the Foreign Sovereign Immunity Act only applies when the suit is based upon activity that took place in the United States, and it was not sufficient to establish a single element of the claim in question.","sumSrc":"Oyez","by":{"3":"5"}},{"t":"case","label":"Payne v. Tennessee","cite":"501 U.S. 808","y":1991,"id":"1990/90-5721","sc":1,"sum":"The Court reasoned that since \"[v]irtually no limits are placed on the relevant mitigating evidence a capital defendant may introduce concerning his own circumstances,\" the prosecution must be allowed to submit similar counter evidence.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"Somerlott v. Cherokee Nation Distribs., Inc.","cite":"686 F.3d 1144","y":2012,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/686/1144/","by":{"3":"21"}},{"t":"case","label":"State Oil Co. v. Khan","cite":"522 U.S. 3","y":1997,"id":"1997/96-871","sc":1,"sum":"The Court noted that antitrust cases are typically decided by weighing the costs and benefits of restrictions in each individual case instead of by per se rules as in Albrecht . Also, there was significant precedent contradicting the assertion that all trade restrictions are illegal, and there was evidence that the effects of price-fixing are not as detrimental as the Court thought at the time of Albrecht .","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"Taylor v. Freeland & Kronz","cite":"503 U.S. 638","y":1992,"id":"1991/91-571","sc":1,"sum":"A trustee may not contest the validity of a claimed exemption after the Rule 4003(b) 30-day period has expired, even though the debtor had no colorable basis for claiming the exemption..","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"3"}},{"t":"case","label":"United States v. Jicarilla Apache Nation","cite":"564 U.S. 162","y":2011,"id":"2010/10-382","sc":1,"sum":"The Court held that the fiduciary exception to the attorney-client privilege does not apply to the general trust relationship between the United States and the Indian Tribes.","sumSrc":"Oyez","by":{"3":"2, 21"}},{"t":"case","label":"United States v. Lee","cite":"106 U.S. 196","y":1882,"id":"scdb/1882-052","sc":1,"by":{"3":"6"}},{"t":"case","label":"Va. Office for Prot. & Advocacy v. Stewart","cite":"563 U.S. 247","y":2011,"id":"2010/09-529","sc":1,"sum":"The Court held that a federal court may hear a lawsuit for prospective injunctive relief against state officials brought by another agency of the same state.","sumSrc":"Oyez","by":{"3":"11"}}]};